// audit appends a row to the audit log on behalf of the authenticated user.
// It writes a server error response and returns false when the row cannot be appended.
// @effects: writes audit_log
func (h *handler) audit(w http.ResponseWriter, r *http.Request, tableName, action string, rowID int64) bool {
	if err := h.store.AppendAuditLog(request.UserID(r), tableName, action, rowID); err != nil {
		response.JSONServerError(w, r, err)
		return false
	}
	return true
}

